import fs from 'node:fs'
import { PNG } from 'pngjs'
import pixelmatch from 'pixelmatch'

const a = PNG.sync.read(fs.readFileSync(process.argv[2]))
const b = PNG.sync.read(fs.readFileSync(process.argv[3]))
const w = Math.min(a.width, b.width), h = Math.min(a.height, b.height)
const crop = p => { const t = new PNG({ width: w, height: h }); PNG.bitblt(p, t, 0, 0, w, h, 0, 0); return t }
const diff = new PNG({ width: w, height: h })
const n = pixelmatch(crop(a).data, crop(b).data, diff.data, w, h, { threshold: 0.1, includeAA: false })
fs.writeFileSync(process.argv[4], PNG.sync.write(diff))
console.log('similarity', (100 * (1 - n / (w * h))).toFixed(2) + '%', 'diffpx', n)

