/**
 * 图表区对齐比对：裁掉 navbar(顶部 60px) 后 pixelmatch，并断言 navbar 区 diff=0。
 * 用法: node scripts/mm-align.mjs <refPng> <implPng> [outDir]
 * 固定口径：1920x1080, DPR=1, crop y=60..1080 (h=1020), 全宽 1920。
 * 判定：图表区相似度 >= 98%。
 */
import fs from 'node:fs'
import path from 'node:path'
import { PNG } from 'pngjs'
import pixelmatch from 'pixelmatch'

const [refPng, implPng, outDir = 'test-results'] = process.argv.slice(2)
const NAV_H = 60
const THRESHOLD = 98

const A = PNG.sync.read(fs.readFileSync(refPng))
const B = PNG.sync.read(fs.readFileSync(implPng))
const W = Math.min(A.width, B.width), H = Math.min(A.height, B.height)
if (A.width !== B.width || A.height !== B.height) {
  console.log(`WARN size mismatch A=${A.width}x${A.height} B=${B.width}x${B.height}`)
}

function cropPNG(src, x, y, w, h) {
  const t = new PNG({ width: w, height: h })
  PNG.bitblt(src, t, x, y, w, h, 0, 0)
  return t
}

// 1) 图表区（y>=NAV_H）
const cw = W, ch = H - NAV_H
const ca = cropPNG(A, 0, NAV_H, cw, ch)
const cb = cropPNG(B, 0, NAV_H, cw, ch)
const d1 = new PNG({ width: cw, height: ch })
const n1 = pixelmatch(ca.data, cb.data, d1.data, cw, ch, { threshold: 0.1, includeAA: false })
fs.mkdirSync(outDir, { recursive: true })
fs.writeFileSync(path.join(outDir, 'mm-chart-diff.png'), PNG.sync.write(d1))
const chartPct = 100 * (1 - n1 / (cw * ch))
console.log(`[图表区 y>=${NAV_H}] 相似度 ${chartPct.toFixed(3)}%  diffpx=${n1}/${cw * ch}`)

// 2) navbar 区（y<NAV_H）应无差异（本任务不动 navbar）
const na = cropPNG(A, 0, 0, W, NAV_H)
const nb = cropPNG(B, 0, 0, W, NAV_H)
const dn = new PNG({ width: W, height: NAV_H })
const nn = pixelmatch(na.data, nb.data, dn.data, W, NAV_H, { threshold: 0.1, includeAA: false })
fs.writeFileSync(path.join(outDir, 'mm-navbar-diff.png'), PNG.sync.write(dn))
const navPct = 100 * (1 - nn / (W * NAV_H))
console.log(`[navbar y<${NAV_H}] 相似度 ${navPct.toFixed(3)}%  diffpx=${nn}/${W * NAV_H}（参考，不计入门禁）`)

console.log(`\n门禁: 图表区 >= ${THRESHOLD}% → ${chartPct >= THRESHOLD ? 'PASS' : 'FAIL'}`)
process.exit(chartPct >= THRESHOLD ? 0 : 2)

